SELECT id, budget, SUM(budget) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_budget, COUNT(budget) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_budget, MIN(budget) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_budget, LAG(budget, 1, 0) OVER (PARTITION BY location, dept_name ORDER BY budget, id) AS prev_budget FROM departments WHERE dept_name IN ('Marketing', 'HR', 'Finance');
